NUMERIC=[]
def verify(name,a,b):
 assert math.isclose(a,b,rel_tol=1e-8,abs_tol=1e-8),(name,a,b)
 NUMERIC.append(name)
def angle(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(u[i]*v[i] for i in (0,1))/(dist(p[a],p[o])*dist(p[b],p[o]))))))
def line_circle(r,d):
 p=dict(O=[0,0],H=[0,d],_r=[r,0],_L=[-r-2,d],_R=[r+2,d]);v=sc('O',[],lines=[['_L','_R']],circles=[circle('O','_r')]);w=more(v,ps='H',segs=[['O','H']],rightAngles=[rt('O','H','_R')])
 return p,v,w,[perp('O','H','_L','_R'),ratio('O','H','O','_r',d/r)]
def two_circles(R,r,d,centres=('O1','O2')):
 a,b=centres;p={a:[0,0],b:[d,0],'_R':[0,R],'_r':[d,r]};v=sc([a,b],[],circles=[circle(a,'_R'),circle(b,'_r')]);return p,v,[ratio(a,'_R',b,'_r',R/r),ratio(a,b,a,'_R',d/R)]
def common_tangents(p,v,R,r,d):
 w=deepcopy(v);w['lines']=[];checks=[];count=0
 for sign in [1,-1]:
  nx=(R-sign*r)/d
  if abs(nx)>1+1e-10:continue
  for ny in ([0] if abs(abs(nx)-1)<1e-10 else [math.sqrt(1-nx*nx),-math.sqrt(1-nx*nx)]):
   count+=1;a='_a'+str(count);b='_b'+str(count);u='_u'+str(count);z='_z'+str(count)
   p[a]=[R*nx,R*ny];p[b]=[d+sign*r*nx,sign*r*ny]
   tangent=[-ny,nx];p[u]=[p[a][i]-3*tangent[i] for i in (0,1)];p[z]=[p[a][i]+3*tangent[i] for i in (0,1)]
   w['lines'].append([u,z]);checks += [perp('O1',a,u,z),perp('O2',b,u,z),equal(('O1',a),('O1','_R')),equal(('O2',b),('O2','_r'))]
 return w,checks,count

