B.add(758,'single','Докажите: если расстояние между центрами двух окружностей равно сумме их радиусов, окружности касаются внешним образом.','При O₁O₂ = R + r окружности имеют единственную общую точку K на отрезке O₁O₂ и касаются внешним образом.',[
 row('Построй общую точку.','На отрезке O₁O₂ отложи O₁K = R. Поскольку O₁O₂ = R + r и r > 0, K лежит между центрами; KO₂ = r. Поэтому K принадлежит обеим окружностям.','Сложение отрезков и определение окружности.',[7,21]),
 row('Может ли быть другая общая точка?','Для общей точки M было бы O₁M + MO₂ = R + r = O₁O₂. Если M не на отрезке центров, строгое неравенство треугольника запрещает это равенство. На отрезке центров точка с O₁M = R единственна — это K.','Неравенство треугольника.',34),
 row('Почему касание внешнее?','Для любой точки M второй окружности O₁M ≥ O₁O₂ − O₂M = R; равенство возможно только при M = K. Все остальные её точки лежат вне первой окружности. Следовательно, касание внешнее.','Неравенство треугольника и определение внешнего касания.',[34,77])],p,v,[w,z,z],checks=ch+[col('O1','K','O2'),equal(('O1','K'),('O1','_R')),equal(('O2','K'),('O2','_r')),equal(('O2','M'),('O2','_r'))],labels={'O1':'O₁','O2':'O₂'},printed=[198])
p,v,ch=two_circles(5,3,10);p['M']=polar(p['O2'],120,3);w=more(v,ps='M',segs=[['O1','O2'],['O1','M'],['O2','M']])
B.add(759,'single','Докажите: если расстояние между центрами окружностей больше суммы их радиусов, то общих точек нет и одна окружность лежит вне другой.','При d > R + r все точки каждой окружности лежат вне другой окружности.',[
 row('Возьми произвольную точку на второй окружности.','Пусть M принадлежит окружности центра O₂ радиуса r. Тогда O₂M = r.','Определение окружности.',21),
 row('Оцени расстояние до первого центра.','По неравенству треугольника O₁M ≥ O₁O₂ − O₂M = d − r. Из d > R + r следует d − r > R, значит O₁M > R.','Неравенство треугольника.',34),
 row('Сделай вывод для всех точек.','Каждая точка второй окружности находится вне первой. Меняя окружности местами, получаем тот же вывод для первой. Поэтому общих точек нет, и окружности расположены вне друг друга.','Произвольность выбранной точки.',77)],p,v,[w,w,w],checks=ch+[equal(('O2','M'),('O2','_r'))],labels={'O1':'O₁','O2':'O₂'},printed=[198])
p,v,ch=two_circles(7,2,3);p['M']=polar(p['O2'],60,2);w=more(v,ps='M',segs=[['O1','O2'],['O1','M'],['O2','M']]);q=dict(O=[0,0],A=[7,0],B=[0,2]);qv=sc('O',[],circles=[circle('O','A'),circle('O','B')])
B.add(760,'single','Докажите: если расстояние между центрами окружностей с неравными радиусами меньше разности большего и меньшего радиусов, одна окружность лежит внутри другой.','При R > r и d < R − r окружность радиуса r целиком лежит внутри окружности радиуса R; общих точек нет.',[
 row('Уточни обозначения.','Пусть O₁ — центр большей окружности радиуса R, O₂ — центр меньшей радиуса r. Возьми произвольную точку M меньшей окружности: O₂M = r.','Выбор обозначений и определение окружности.',21),
 row('Оцени расстояние O₁M.','По неравенству треугольника O₁M ≤ O₁O₂ + O₂M = d + r. Из d < R − r следует d + r < R, поэтому O₁M < R.','Неравенство треугольника.',34),
 row('Заверши доказательство.','Каждая точка меньшей окружности лежит внутри большей, поэтому общих точек нет. Рассуждение работает и при совпадении центров: тогда d = 0 и O₁M = r < R.','Определение внутренней точки окружности.',77)],p,v,[w,w,w],checks=ch+[equal(('O2','M'),('O2','_r'))],cases=[(q,qv,'Совпадающие центры и разные радиусы',3,[ratio('O','B','O','A',2/7)])],labels={'O1':'O₁','O2':'O₂'},printed=[199])
p=dict(O=[0,0],M=[8,0],O1=[4,0],_r=[0,3],K=[9/8,math.sqrt(495)/8],K1=[9/8,-math.sqrt(495)/8]);v=sc('OM',[],circles=[circle('O','_r')]);w=more(v,ps=['O1'],segs=[['O','M']],equalSegments=[eq('O','O1'),eq('O1','M')]);z=more(w,circles=[circle('O','_r'),circle('O1','M')]);t=more(z,ps=['K','K1'],segs=[['M','K'],['M','K1'],['O','K'],['O','K1']],rightAngles=[rt('O','K','M'),rt('O','K1','M')])
B.add(761,'single','Постройте касательную к данной окружности, проходящую через данную точку вне окружности.','Построй окружность на диаметре OM. Её пересечения K и K₁ с данной окружностью задают две касательные MK и MK₁.',[
 row('Как подготовить вспомогательную окружность?','Обозначь центр данной окружности O, внешнюю точку M. Построй середину O₁ отрезка OM.','Построение середины отрезка.',23),
 row('Построй окружность на диаметре OM.','Проведи окружность центра O₁ радиуса O₁M. Она пересекает исходную окружность в двух точках K и K₁: если OM = d > R, то |d/2 − R| < d/2 < d/2 + R.','Критерий пересечения двух окружностей.',77),
 row('Проведи искомые прямые и обоснуй.','Соедини M с K и K₁. Углы OKM и OK₁M опираются на диаметр OM вспомогательной окружности, поэтому прямые. Радиусы OK и OK₁ перпендикулярны построенным прямым, значит это касательные.','Вписанный угол, опирающийся на полуокружность; признак касательной.',[80,76]),
 row('Почему найдены все решения?','Любая касательная через M касается в точке T, для которой OT ⟂ MT. Такая T лежит на окружности с диаметром OM, следовательно совпадает с K или K₁. Итого ровно два решения.','Признак касательной и обратное описание окружности на диаметре.',[76,80])],p,v,[w,z,t,t],checks=[equal(('O','K'),('O','K1'),('O','_r')),equal(('O1','O'),('O1','M'),('O1','K'),('O1','K1')),perp('O','K','M','K'),perp('O','K1','M','K1')],labels={'O1':'O₁','K1':'K₁'},printed=[199])
for part,degrees in [('а',60),('б',90),('в',120),('г',180)]:
 p=dict(O=[0,0],A=[5,0],B=polar([0,0],degrees,5));v=sc('OA',[],circles=[circle('O','A')]);w=more(v,ps='B',segs=[['O','A'],['O','B']],angleArcs=[arc('O','A','B')]);z=more(w,segs=[['A','B']]);method={60:'Построй равносторонний треугольник OAB на стороне OA: его третья вершина B лежит на окружности.',90:'Восстанови в O перпендикуляр к OA и отметь B на его пересечении с окружностью.',120:'Сначала построй луч, образующий с OA угол 60°, а затем его продолжение за O. На противоположном луче выбери точку B окружности: 180° − 60° = 120°.',180:'Продолжи AO за O до второго пересечения B с окружностью. Получится диаметр AB.'}[degrees]
 B.add(762,part,f'Начертите окружность с центром O и отметьте на ней A. Постройте хорду AB так, чтобы ∠AOB = {degrees}°.','Нужно выбрать B на окружности на луче из O под углом '+str(degrees)+'° к OA и соединить A с B.',[row('Как построить нужный луч и точку B?',method,'Построения углов 60°, 90° и смежных углов.',[18,23,11]),row('Почему AB — нужная хорда?','A и B принадлежат окружности, поэтому AB — хорда. По построению центральный угол AOB равен '+str(degrees)+'°.','Определение хорды и центрального угла.',[21,79])],p,v,[w,z],checks=[equal(('O','A'),('O','B')),ang('A','O','B',degrees)],printed=[204])
for part,degrees,ans,calc in [('а',60,'16','Треугольник OAB равнобедренный, а угол AOB равен 60°. Оба остальных угла равны (180° − 60°)/2 = 60°, поэтому треугольник равносторонний и AB = OA = 16.'),('б',90,'16√2','Треугольник OAB прямоугольный при O, поэтому AB² = OA² + OB² = 16² + 16² = 512. Следовательно, AB = 16√2.'),('в',180,'32','Лучи OA и OB противоположны; AB — диаметр. Поэтому AB = OA + OB = 16 + 16 = 32.')]:
 p=dict(O=[0,0],A=[16,0],B=polar([0,0],degrees,16));v=sc('OAB',[['O','A'],['O','B'],['A','B']],circles=[circle('O','A')],angleArcs=[arc('O','A','B')]);w=more(v,equalSegments=[eq('O','A'),eq('O','B')]);verify('763'+part,dist(p['A'],p['B']),{'а':16,'б':16*math.sqrt(2),'в':32}[part])
 B.add(763,part,f'Радиус окружности с центром O равен 16. Найдите хорду AB, если ∠AOB = {degrees}°.','AB = '+ans+'.',[row('Какие отрезки известны?','OA = OB = 16, поскольку это радиусы одной окружности.','Равенство радиусов.',21),row('Используй данный центральный угол.',calc,'Равнобедренный треугольник, теорема Пифагора или определение диаметра.',[18,60,79])],p,v,[w,w],checks=[equal(('O','A'),('O','B')),ang('A','O','B',degrees)],printed=[204])
