 B.add(764,part,'Хорды AB и CD окружности с центром O равны. '+('Докажите, что две дуги с концами A и B соответственно равны двум дугам с концами C и D.' if part=='а' else 'Найдите две дуги с концами C и D, если ∠AOB = 112°.'),('Меньшие дуги равны друг другу, большие — друг другу; для диаметров все дуги равны 180°.' if part=='а' else '112° и 248°.'),steps,p,v,[w]*len(steps),checks=[equal(('A','B'),('C','D')),equal(('O','A'),('O','B'),('O','C'),('O','D')),ang('A','O','B',112),ang('C','O','D',112)],cases=([(q,qv,'Обе хорды — диаметры',2,[col('A','O','B'),col('C','O','D'),equal(('A','B'),('C','D'))])] if part=='а' else []),printed=[204])
